def is_valid_vpa(s):
    if len(s) < 5 or len(s) > 260:
        return False
    if not s.startswith('@'):
        return False
    handle, provider = s[1:].split('@', 1)
    if len(handle) < 2 or len(handle) > 256:
        return False
    if not handle.replace('.', '').replace('-', '').isalnum():
        return False
    if len(provider) < 2 or len(provider) > 64:
        return False
    if not provider.isalpha():
        return False
    return True

